<?php
require_once 'includes/config.php'; require_once 'includes/phase3.php'; require_admin();
$search=trim($_GET['q']??'');$status=isset($_GET['status'])?trim($_GET['status']):'';$p=[];$where=['1=1'];if($search){$where[]='(t.full_name LIKE :q OR t.username LIKE :q)';$p[':q']='%'.$search.'%';}if($status!==''){$where[]='t.status=:st';$p[':st']=(int)$status;}
$sql="SELECT t.id,t.full_name,t.username,t.gender,t.status,COUNT(DISTINCT a.class_id) classes,COUNT(DISTINCT a.student_id) students,COUNT(DISTINCT CASE WHEN rs.submission_status='pending' THEN rs.id END) pending,COUNT(DISTINCT CASE WHEN rs.submission_status='rework' THEN rs.id END) rework,COUNT(DISTINCT CASE WHEN rs.submission_status='approved' THEN rs.id END) approved,COUNT(DISTINCT rs.id) submissions FROM teachers t LEFT JOIN teacher_student_assignments a ON a.teacher_id=t.id LEFT JOIN result_submissions rs ON rs.teacher_id=t.id WHERE ".implode(' AND ',$where)." GROUP BY t.id ORDER BY t.full_name";
$q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll();$classes=$dbh->query("SELECT t.id,t.full_name,c.ClassName,c.Section,COUNT(DISTINCT a.student_id) students FROM teachers t JOIN teacher_class_assignments ca ON ca.teacher_id=t.id JOIN tblclasses c ON c.id=ca.class_id LEFT JOIN teacher_student_assignments a ON a.teacher_id=t.id AND a.class_id=c.id GROUP BY t.id,c.id ORDER BY t.full_name,c.ClassNameNumeric,c.Section")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Workload | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-sm-8"><h2 class="title">Teacher Workload Dashboard</h2><p class="text-muted">Assignment and grading workload across the teacher team.</p></div></div><form class="panel panel-default panel-body" method="get"><div class="row"><div class="col-md-6"><label>Search teacher</label><input class="form-control" name="q" value="<?php echo e($search);?>" placeholder="Name or username"></div><div class="col-md-4"><label>Status</label><select class="form-control" name="status"><option value="">All</option><option value="1" <?php echo $status==='1'?'selected':'';?>>Active</option><option value="0" <?php echo $status==='0'?'selected':'';?>>Disabled</option></select></div><div class="col-md-2"><label>&nbsp;</label><button class="btn btn-primary btn-block">Filter</button></div></div></form><div class="panel"><div class="panel-heading"><h4>Workload Summary</h4></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Teacher</th><th>Status</th><th>Classes</th><th>Students</th><th>Pending</th><th>Rework</th><th>Approved</th><th>Total Submissions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?php echo e($r['full_name']);?></strong><br><small><?php echo e($r['username']);?></small></td><td><span class="label label-<?php echo $r['status']?'success':'default';?>"><?php echo $r['status']?'Active':'Disabled';?></span></td><td><?php echo (int)$r['classes'];?></td><td><?php echo (int)$r['students'];?></td><td><span class="label label-warning"><?php echo (int)$r['pending'];?></span></td><td><span class="label label-danger"><?php echo (int)$r['rework'];?></span></td><td><span class="label label-success"><?php echo (int)$r['approved'];?></span></td><td><?php echo (int)$r['submissions'];?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center">No teachers found.</td></tr><?php endif;?></tbody></table></div></div></div><div class="panel"><div class="panel-heading"><h4>Class Assignments</h4></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Teacher</th><th>Class</th><th>Assigned Students</th></tr></thead><tbody><?php foreach($classes as $r):?><tr><td><?php echo e($r['full_name']);?></td><td><?php echo e($r['ClassName'].' '.$r['Section']);?></td><td><?php echo (int)$r['students'];?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
